import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Politique de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy.md","filePath":"fr/guide/privacy.md","lastUpdated":1793173149000}`),a={name:`fr/guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="politique-de-confidentialite" tabindex="-1">Politique de confidentialité <a class="header-anchor" href="#politique-de-confidentialite" aria-label="Permalink to “Politique de confidentialité”">​</a></h1><p>Sudoku est une application conçue hors ligne en priorité, avec des fonctions cloud facultatives. Cette page explique quelles données (le cas échéant) l&#39;application collecte et comment elles sont utilisées.</p><h2 id="cœur-hors-ligne-—-aucune-collecte-de-donnees-pour-le-jeu" tabindex="-1">Cœur hors ligne — aucune collecte de données pour le jeu <a class="header-anchor" href="#cœur-hors-ligne-—-aucune-collecte-de-donnees-pour-le-jeu" aria-label="Permalink to “Cœur hors ligne — aucune collecte de données pour le jeu”">​</a></h2><ul><li>Le jeu de puzzle principal est entièrement jouable hors ligne. Aucun accès réseau n&#39;est nécessaire pour jouer.</li><li>Toutes les données de jeu — réglages, état de la partie, notes au crayon et statistiques — sont stockées localement sur votre appareil.</li><li>Il n&#39;y a ni publicité, ni analyse d&#39;audience, ni SDK de suivi tiers.</li></ul><h2 id="fonctions-cloud-facultatives" tabindex="-1">Fonctions cloud facultatives <a class="header-anchor" href="#fonctions-cloud-facultatives" aria-label="Permalink to “Fonctions cloud facultatives”">​</a></h2><h3 id="synchronisation-icloud-cloudkit" tabindex="-1">Synchronisation iCloud (CloudKit) <a class="header-anchor" href="#synchronisation-icloud-cloudkit" aria-label="Permalink to “Synchronisation iCloud (CloudKit)”">​</a></h3><p>Lorsque vous vous connectez à iCloud et activez la synchronisation :</p><ul><li>Les parties sauvegardées, les statistiques, les réglages et la progression du défi quotidien sont synchronisés vers votre <strong>compte iCloud personnel</strong> via le service CloudKit d&#39;Apple.</li><li>Les données sont chiffrées en transit et au repos par l&#39;infrastructure d&#39;Apple.</li><li>Vous seul pouvez accéder à vos données synchronisées à l&#39;aide de votre identifiant Apple.</li><li>Cette fonction est entièrement facultative — l&#39;application fonctionne parfaitement sans elle.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Lorsque vous vous connectez à Game Center :</p><ul><li>Les scores des classements (meilleurs temps de résolution par niveau de difficulté) peuvent être partagés sur des classements publics.</li><li>La progression des succès est enregistrée par le service Game Center d&#39;Apple.</li><li>Votre nom d&#39;affichage Game Center est visible par les autres joueurs dans les classements.</li><li>Cette fonction est entièrement facultative.</li></ul><h2 id="le-seul-autre-acces-reseau-«-plus-d-apps-»" tabindex="-1">Le seul autre accès réseau : « Plus d&#39;apps » <a class="header-anchor" href="#le-seul-autre-acces-reseau-«-plus-d-apps-»" aria-label="Permalink to “Le seul autre accès réseau : « Plus d&#39;apps »”">​</a></h2><p>La seule fonction réseau hors cloud est une section facultative <strong>« Plus d&#39;apps »</strong> dans les réglages, qui récupère auprès de nos serveurs une liste d&#39;applications de la même famille. Cette fonction :</p><ul><li>Ne s&#39;active que lorsque vous ouvrez Réglages → Plus d&#39;apps.</li><li>Récupère une liste légère de noms et de liens d&#39;applications — aucune donnée personnelle n&#39;est envoyée ni stockée.</li><li>Peut être totalement ignorée et n&#39;affecte en rien le jeu.</li></ul><h2 id="ce-que-nous-ne-collectons-pas" tabindex="-1">Ce que nous ne collectons pas <a class="header-anchor" href="#ce-que-nous-ne-collectons-pas" aria-label="Permalink to “Ce que nous ne collectons pas”">​</a></h2><ul><li>Nous ne collectons ni informations personnelles, ni fichiers, ni images, ni historique de navigation.</li><li>Nous n&#39;envoyons aucune donnée de jeu vers des serveurs externes (sauf dans les cas décrits ci-dessus pour iCloud et Game Center).</li><li>Nous n&#39;intégrons aucun SDK d&#39;analyse d&#39;audience ou de publicité tiers.</li><li>Nous n&#39;utilisons aucun service de rapport de plantage ni de télémétrie.</li></ul><h2 id="autorisations" tabindex="-1">Autorisations <a class="header-anchor" href="#autorisations" aria-label="Permalink to “Autorisations”">​</a></h2><p>Sudoku requiert un minimum d&#39;autorisations :</p><ul><li><strong>iCloud</strong> (facultatif) : pour synchroniser les données de jeu entre appareils via CloudKit.</li><li><strong>Game Center</strong> (facultatif) : pour les classements et les succès.</li><li><strong>Réseau</strong> (facultatif) : pour la synchronisation iCloud, Game Center et « Plus d&#39;apps ».</li></ul><p>Aucune autorisation de localisation, de contacts, d&#39;appareil photo, de microphone ou d&#39;autre autorisation sensible n&#39;est demandée.</p><h2 id="conservation-des-donnees" tabindex="-1">Conservation des données <a class="header-anchor" href="#conservation-des-donnees" aria-label="Permalink to “Conservation des données”">​</a></h2><ul><li>Les données locales restent sur votre appareil jusqu&#39;à ce que vous désinstalliez ou réinitialisiez l&#39;application.</li><li>Les données synchronisées via iCloud suivent la politique de conservation des données iCloud d&#39;Apple.</li><li>Les données Game Center suivent les politiques Game Center d&#39;Apple.</li></ul><h2 id="demandes-relatives-a-la-confidentialite" tabindex="-1">Demandes relatives à la confidentialité <a class="header-anchor" href="#demandes-relatives-a-la-confidentialite" aria-label="Permalink to “Demandes relatives à la confidentialité”">​</a></h2><p>Étant donné que Sudoku stocke toutes les données localement (et, si vous le souhaitez, dans votre iCloud personnel), aucun serveur de notre côté ne détient ou ne consulte de données. Pour effacer toutes les données de l&#39;application :</p><ul><li><strong>Désinstallez l&#39;application</strong> de votre ou vos appareils.</li><li><strong>Réinitialisez les données iCloud</strong> : dans Réglages → [Votre nom] → iCloud → Gérer le stockage du compte → Sudoku → Supprimer les données.</li><li><strong>Réinitialisation locale sur Mac</strong> : consultez le guide de dépannage pour les instructions de suppression du conteneur.</li></ul><h2 id="confidentialite-des-enfants" tabindex="-1">Confidentialité des enfants <a class="header-anchor" href="#confidentialite-des-enfants" aria-label="Permalink to “Confidentialité des enfants”">​</a></h2><p>Sudoku ne collecte activement aucune information personnelle, y compris auprès des enfants. L&#39;application ne nécessite ni compte, ni fonction de messagerie, ni réseau social.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>Pour toute question relative à la confidentialité, ouvrez une issue sur le dépôt du projet (<a href="https://github.com/sudoku-pro/sudoku-site" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site</a>) ou écrivez-nous à <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};